def solve(k1=2.5e-15, k2=1.5e-13, CH4_ppbv=1700.0, CO_NH_ppbv=80.0, CO_SH_ppbv=50.0, growth_loss_fraction=0.5):
    frac_NH = k1 * CH4_ppbv / ((1.0 + growth_loss_fraction) * k2 * CO_NH_ppbv)
    frac_SH = k1 * CH4_ppbv / ((1.0 + growth_loss_fraction) * k2 * CO_SH_ppbv)
    pct_NH = frac_NH * 100.0
    pct_SH = frac_SH * 100.0
    return {'1': {'value': pct_NH, 'unit': '%'}, '2': {'value': pct_SH, 'unit': '%'}}

