def solve(g_over_Tve=0.0333, Cw=5, zi=11000.0, delta_theta=5.0, r_l_g_kg=5.0, g=9.81):
    import math
    r_l = r_l_g_kg / 1000.0
    buoyancy = g_over_Tve * delta_theta - g * r_l
    W = math.sqrt(zi / Cw * buoyancy)
    return {'1': {'value': W, 'unit': 'm/s'}}

def solve(angle_deg=30.0, V=20.0, Vg=20.0, f=0.0001, r=0.0001):
    import math
    angle_rad = math.radians(angle_deg)
    dVdt = -f * Vg * math.sin(angle_rad) - r * V
    return {'1': {'value': dVdt, 'unit': 'm s^-2'}}

def solve(surface_temperature_K=288.0, solar_constant_W_m2=1370.0, infrared_optical_depth=2.0):
    import math
    stefan_boltzmann_constant_W_m2_K4 = 5.670374419e-08
    absorptivity_increment_threshold = solar_constant_W_m2 / (2.0 * stefan_boltzmann_constant_W_m2_K4 * surface_temperature_K ** 4)
    optical_depth_increment_threshold = absorptivity_increment_threshold * math.exp(infrared_optical_depth)
    return {'1': {'value': optical_depth_increment_threshold, 'unit': 'dimensionless'}}

def solve(T0_C=-20.0, wl_g_per_kg=10.0, cp=1005.0, Lf=3.34e5, Ls=2.83e6):
    T_tab = [-23.0, -22.0, -21.0, -20.0, -19.0, -18.0, -17.0, -16.0]
    ws_tab = [1.002, 1.094, 1.194, 1.303, 1.420, 1.546, 1.682, 1.824]
    wi_tab = [0.800, 0.883, 0.973, 1.072, 1.179, 1.296, 1.425, 1.565]

    def interp(T, tab):
        for i in range(len(T_tab) - 1):
            if T_tab[i] <= T <= T_tab[i + 1]:
                f = (T - T_tab[i])/(T_tab[i + 1] - T_tab[i])
                return tab[i] + f*(tab[i + 1] - tab[i])
        raise ValueError("outside the tabulated range")

    wl = wl_g_per_kg*1e-3
    ws0 = interp(T0_C, ws_tab)*1e-3          # the parcel starts saturated over water
    T = T0_C
    for _ in range(500):
        # SIGNED: once the fusion warming carries the parcel past ice saturation the vapour
        # budget reverses and ice sublimates, absorbing Ls instead of releasing it
        dep = ws0 - interp(T, wi_tab)*1e-3
        T = T0_C + (Lf*wl + Ls*dep)/cp
    return {"1": {"value": T - T0_C, "unit": "K"}}
